const PERMITIDOS=['https://painel.bodhi.marketing','http://localhost:5173'];export default{async fetch(q){if(q.method!=='GET'&&q.method!=='HEAD')return new Response('Metodo nao permitido',{status:405});const d=q.headers.get('Origin')||q.headers.get('Referer')||'';if(!PERMITIDOS.some(o=>d===o||d.startsWith(o+'/')))return new Response('Acesso negado',{status:403});const id=new URL(q.url).searchParams.get('id')||'';if(!/^[\w-]{20,}$/.test(id))return new Response('Arquivo invalido',{status:400});const h=new Headers();const f=q.headers.get('Range');if(f)h.set('Range',f);const r=await fetch('https://drive.usercontent.google.com/download?id='+id+'&export=download&confirm=t',{headers:h,redirect:'follow'});const t=r.headers.get('content-type')||'';if(!r.ok&&r.status!==206)return new Response('O Drive nao entregou o arquivo',{status:502});if(!/^(video|audio)\//.test(t))return new Response('O Drive nao liberou este video agora',{status:502});const s=new Headers();for(const k of['content-type','content-length','content-range','accept-ranges','etag','last-modified']){if(r.headers.has(k))s.set(k,r.headers.get(k))}s.set('Accept-Ranges','bytes');s.set('Cache-Control','public, max-age=3600');s.set('Content-Disposition','inline');s.set('Access-Control-Allow-Origin',d.startsWith('http')?new URL(d).origin:'*');return new Response(r.body,{status:r.status,headers:s})}};
